/* slide menu */
#mobilenav-aast .slide-menu {
    background-color: #f1f1f1;
    position: fixed;
    top: 0;
    right: -100%;
    width: 100%;
    min-height: 100%;
    height: 100%;
    background-color: #f1f1f1;
    transition: all 0.5s ease;
    z-index: 0;
    -webkit-transform: translateX(150%);
    transform: translateX(150%);
