/*****************************events********************/

.ltn__tab-menu-3 {
    margin-top: 0;
}

.ltn__tab-menu .nav {
    display: inline-block;
}

.ltn__tab-menu-3 a {
    background-color: transparent;
    border-bottom: 2px solid transparent;
    padding: 1px;
    margin-right: 50px;
    font-weight: 700;
    font-size: 23px;
    line-height: 1.2;
    position: relative;
}

.tab-content .tab-pane.active {
    height: auto;
    visibility: visible;
    opacity: 1;
    overflow: visible;
}

.tab-content .tab-pane {
